"げこげこ": "Từ chỉ tiếng ếch kêu.",
"てこてこ": "Đi những bước nhỏ nhẹ nhàng.",
"ぱこぱこ": "Tiếng kêu nhẹ, rỗng của vật rỗng ruột.",
"えこえこ": "Tên bộ truyện tranh Eko Eko Azarak, và cụm lặp lại trong câu thần chú trong truyện.",
