"りこりこ": "Tên gọi tắt chính thức của anime truyền hình gốc Lycoris Recoil.",
"がっくり": "Bỗng rũ cả người; thất vọng nặng nề.",
"ぎっくり": "Bị bất ngờ giật mình, hoặc bỗng vặn mình mà bị đau. Như 'gikkuri-goshi'.",
"こっくり": "Gật đầu. / Đầu gục về phía trước khi ngủ gật.",
"ざっくり": "Đại khái, sơ bộ. / Cắt một nhát thô.",
