"しっくり": "Hợp nhau, không có gì gượng gạo.",
"そっくり": "Giống hệt nhau. / Toàn bộ, y nguyên.",
"とっくり": "Kỹ lưỡng, đầy đủ, cẩn thận. / Tokkuri: bình cổ nhỏ dùng đựng và rót rượu sake.",
"びっくり": "Giật mình vì chuyện bất ngờ.",
"ぽっくり": "Chết đột ngột, nhẹ như không. / Gãy đánh tách một cái.",
"むっくり": "Đang nằm bỗng bật dậy.",
"ゆっくり": "Từ từ, không vội.",
