"ぷっくり": "Phồng lên tròn trịa.",
"でっくり": "Béo tròn. Như 'deppuri'.",
"つっくり": "Một mình đứng lặng, chẳng làm gì, hoặc chìm trong suy nghĩ.",
"ばっくり": "Vết thương hay khe hở nứt toác ra.",
"すっくり": "Đứng thẳng dậy dứt khoát. / Hoàn toàn.",
"ちっくり": "Châm nhẹ như bị kim đâm. Tức 'chikuri'.",
"ぼっくり": "Dạng đục hoá của 'pokkuri'. / Dạng còn lại ở cuối từ matsubokkuri (quả thông).",
"ひっくり": "Dùng trong 'hikkurikaeru', 'hikkurikaesu': lật ngược trên dưới, trước sau.",
"さっくり": "Cắt ngọt, nhẹ tay. / Giòn xốp khi cắn. / Đại khái.",
"ふっくり": "Phồng lên mềm mại. Tức 'fukkura'.",
"すかすか": "Bên trong ít, đầy khoảng trống.",
"てかてか": "Bề mặt bóng nhẫy vì dầu, trông không tự nhiên.",
"ぴかぴか": "Sáng lấp lánh. / Sạch bóng như mới.",
"ふかふか": "Mềm và dày xốp.",
"ほかほか": "Vẫn còn ấm nóng.",
"ぽかぽか": "Ấm áp dễ chịu.",
"あかあか": "Sáng rực rỡ. Viết là 赤々.",
"ぱかぱか": "Tiếng vó ngựa lóc cóc nhẹ nhàng. / Vật mở ra khép lại liên tục.",
"むかむか": "Buồn nôn. / Bực bội khó chịu.",
"ぶかぶか": "Quần áo rộng thùng thình.",
"ぷかぷか": "Nổi bồng bềnh trên mặt nước hay trong không trung. / Phì phèo nhả khói thuốc.",
